import * as React from 'react';
import { CommonProps } from '../utility/commonProps';
export interface ChipGroupProps extends Omit<React.ComponentPropsWithoutRef<'div'>, 'className' | 'style'>, CommonProps {
    /**
     * The content for the chip group.
     */
    children: React.ReactNode;
}
/**
 * Chip Groups display multiple related chips in a horizontal row to help with arrangement and spacing.
 *
 * - {@link https://livingdesign.walmart.com/components/chip-group/ Guidelines}
 * - {@link https://livingdesign.walmart.com/components/chip-group/react/ React documentation}
 *
 * ### Content
 *
 * The Chip Group accepts Chip elements through the `children` prop.
 *
 * ```tsx
 * import * as React from "react";
 * import {
 *   Chip,
 *   ChipGroup
 * } from "@walmart-web/livingdesign-components";
 *
 * export default () => {
 *   return (
 *     <ChipGroup>
 *       <Chip>One</Chip>
 *       <Chip>Two</Chip>
 *       <Chip>Three</Chip>
 *     </ChipGroup>
 *   );
 * }
 * ```
 */
export declare const ChipGroup: React.FunctionComponent<ChipGroupProps>;
